def build_report(cases,record_counts,run_started_at,workbook):
    return {"run_started_at":run_started_at,"workbook":str(workbook),"record_counts":record_counts,"cases":[{"case_id":c.case_id,"event_id":c.event_id,"state":c.state,"disposition":c.disposition,"recommendation":c.recommendation,"evidence_gaps":c.gaps,"override_reason":c.override_reason,"reopen_count":c.reopen_count,"prior_case_id":c.prior_case_id,"events":[{"event_id":e.event_id,"event_type":e.event_type,"occurred_at":e.occurred_at.isoformat(),"actor":e.actor,"previous_state":e.previous_state,"new_state":e.new_state,"payload":e.payload} for e in c.events]} for c in cases]}
